import json
import re
import subprocess
import sys
from pathlib import Path, PurePosixPath

HERE = Path(__file__).resolve().parent
REPO_ROOT = HERE.parent.parent
FILTERS_PATH = HERE / "changed-areas.yml"
WORKFLOW_PATH = REPO_ROOT / ".github/workflows/ci.yml"

UNCOVERED = (
    ("assets/**", "Screenshots and logo; no build consumes them."),
    (
        "evaluation/**",
        "Committed evaluation data and reports; not executed by a suite.",
    ),
    ("LICENSE", "License text."),
    ("AGENTS.md", "Repository guidance; Markdown is covered by documentation checks."),
    (".gitattributes", "Git attributes; no build reads them."),
    (".gitignore", "Git ignore rules; no build reads them."),
    (".dockerignore", "Docker ignore rules for the unused root context."),
)


def parse_changed_areas(text: str) -> dict[str, list[str]]:
    areas: dict[str, list[str]] = {}
    current: str | None = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        area_match = re.fullmatch(r"([a-z0-9-]+):", line)
        if area_match:
            current = area_match.group(1)
            areas[current] = []
            continue
        glob_match = re.fullmatch(
            r"-\s*(?:'([^']+)'|\"([^\"]+)\"|([^#\s][^#]*?))", line
        )
        if glob_match:
            if current is None:
                raise AssertionError(f"a glob appears outside any area: {raw}")
            areas[current].append(
                next(value for value in glob_match.groups() if value).strip()
            )
            continue
        raise AssertionError(f"unparsable line in changed-areas.yml: {raw}")
    return areas


def glob_to_pattern(glob: str) -> re.Pattern[str]:
    escaped = re.sub(r"[.+^${}()|[\]\\]", lambda match: f"\\{match.group()}", glob)
    escaped = escaped.replace("**/", "\ue000")
    escaped = escaped.replace("**", "\ue001")
    escaped = escaped.replace("*", "[^/]*")
    escaped = escaped.replace("\ue000", "(?:.*/)?")
    escaped = escaped.replace("\ue001", ".*")
    return re.compile(f"^{escaped}$")


def covers(globs: list[str], candidate: str) -> bool:
    return any(glob_to_pattern(glob).fullmatch(candidate) for glob in globs)


def areas_referenced_by_workflow(source: str) -> set[str]:
    return set(re.findall(r"needs\.changes\.outputs\.([a-z0-9-]+) == 'true'", source))


def declared_change_outputs(source: str) -> set[str]:
    block = re.search(r"^    outputs:\n((?:^      [\w-]+:.*\n)+)", source, re.MULTILINE)
    if block is None:
        raise AssertionError("could not find the `changes` job outputs block")
    return set(re.findall(r"^      ([\w-]+):", block.group(1), re.MULTILINE))


def contract_tool_directories(tracked_files: list[str]) -> list[str]:
    return sorted(
        str(PurePosixPath(file).parent)
        for file in tracked_files
        if re.fullmatch(r"contracts/.+/tools/package\.json", file)
    )


def contract_tool_directories_in_workflow(source: str) -> list[str]:
    return sorted(
        re.findall(
            r"^\s+tools_directory:\s+(contracts/\S+/tools)$", source, re.MULTILINE
        )
    )


def check_area_references(areas: dict[str, list[str]], workflow: str) -> None:
    declared = set(areas)
    referenced = areas_referenced_by_workflow(workflow)
    undeclared = sorted(referenced - declared)
    unused = sorted(declared - referenced)
    if undeclared:
        raise AssertionError(f"a job gates on undeclared area `{undeclared[0]}`")
    if unused:
        raise AssertionError(
            f"the model declares area `{unused[0]}`, but no job gates on it"
        )


def check_change_outputs(areas: dict[str, list[str]], workflow: str) -> None:
    actual = sorted(declared_change_outputs(workflow))
    expected = sorted(areas)
    if actual != expected:
        raise AssertionError(
            f"changes outputs differ: expected {expected}, got {actual}"
        )


def check_generated_artifacts(
    areas: dict[str, list[str]], workflow: str, tracked_files: list[str]
) -> None:
    tool_directories = contract_tool_directories(tracked_files)
    workflow_directories = contract_tool_directories_in_workflow(workflow)
    if workflow_directories != tool_directories:
        raise AssertionError(
            "the contract-tools matrix must run every tracked contract tool exactly once"
        )

    outputs: list[str] = []
    for tool_directory in tool_directories:
        manifest_path = f"{tool_directory}/generated-artifacts.json"
        if manifest_path not in tracked_files:
            raise AssertionError(
                f"{manifest_path} must describe the artifacts generated by its contract tool"
            )
        manifest = json.loads((REPO_ROOT / manifest_path).read_text(encoding="utf-8"))
        generators = manifest.get("generators")
        if not isinstance(generators, list):
            raise TypeError(f"{manifest_path} has no generators")
        outputs.extend(
            output for generator in generators for output in generator["outputs"]
        )
    if not outputs:
        raise AssertionError("expected at least one generated artifact")
    for output in outputs:
        if not covers(areas["contract-tools"], output):
            raise AssertionError(
                "the contract-tools area does not cover generated artifact "
                f"{output}; a hand edit would run no job that detects the drift"
            )


def check_client_server_seam(areas: dict[str, list[str]]) -> None:
    seam_paths = (
        "apps/github-integration/src/review-runs/client.ts",
        "apps/github-integration/src/review-runs/review-runs-api.ts",
    )
    for candidate in seam_paths:
        if not covers(areas["review-runs"], candidate):
            raise AssertionError(f"the review-runs area must trigger on {candidate}")
        if not covers(areas["github-integration"], candidate):
            raise AssertionError(
                f"the github-integration area must trigger on {candidate}"
            )


def check_execution_workflow(areas: dict[str, list[str]]) -> None:
    schema = "contracts/execution-workflow/v1/execution-workflow-input.schema.json"
    if not covers(areas["execution-gateway"], schema):
        raise AssertionError(f"the execution-gateway area must trigger on {schema}")


def check_tracked_files(areas: dict[str, list[str]], tracked_files: list[str]) -> None:
    all_globs = [glob for globs in areas.values() for glob in globs]
    uncovered_globs = [glob for glob, _ in UNCOVERED]
    invisible = [
        file
        for file in tracked_files
        if not covers(all_globs, file) and not covers(uncovered_globs, file)
    ]
    if invisible:
        suffix = " ..." if len(invisible) > 20 else ""
        raise AssertionError(
            "these tracked files are neither covered by an area nor listed in UNCOVERED: "
            + ", ".join(invisible[:20])
            + suffix
        )


def main() -> int:
    areas = parse_changed_areas(FILTERS_PATH.read_text(encoding="utf-8"))
    workflow = WORKFLOW_PATH.read_text(encoding="utf-8")
    tracked_files = subprocess.run(
        ["git", "ls-files"],
        cwd=REPO_ROOT,
        check=True,
        capture_output=True,
        text=True,
    ).stdout.splitlines()

    checks = (
        ("area references", lambda: check_area_references(areas, workflow)),
        ("change outputs", lambda: check_change_outputs(areas, workflow)),
        (
            "generated artifacts",
            lambda: check_generated_artifacts(areas, workflow, tracked_files),
        ),
        ("client/server seam", lambda: check_client_server_seam(areas)),
        ("Execution Workflow coverage", lambda: check_execution_workflow(areas)),
        ("tracked-file coverage", lambda: check_tracked_files(areas, tracked_files)),
    )
    for name, check in checks:
        try:
            check()
        except (AssertionError, KeyError, TypeError, ValueError) as error:
            print(f"error: {name}: {error}", file=sys.stderr)
            return 1
        print(f"ok: {name}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
